import React from 'react';
import { Link } from 'react-router-dom';
import './Hero.css';

function TopNavbar({ onToggleSidebar, selectedCategory = 'All', onSelectCategory }) {
  const categories = ['All', 'Electronics', 'Fashion', 'Home & Kitchen', 'Furnitures'];

  return (
    <div className="amazon-header">
      {/* Top Row: Logo, Search, Account, Cart */}
      <div className="top-search-row">
        <div className="nav-lo">
          <Link to="/">HEX<span>CART</span></Link>
        </div>

        <div className="top-nav-search">
          <input type="text" placeholder="Search HEXCART..." />
          <button className="top-search-btn"></button>
        </div>

        <div className="top-nav-actions">
          <Link to="/login" className="top-nav-link">
            Hello, sign in <br />
            <span>Account & Lists</span>
          </Link>
          <Link to="/orders" className="top-nav-link">
            Returns <br />
            <span>& Orders</span>
          </Link>
          <Link to="/cart" className="top-cart-link">
             Cart
          </Link>
        </div>
      </div>

      {/* Bottom Row: Navigation Links & Categories integrated together */}
      <div className="sub-nav-row">
        <div className="sub-nav-links">
          {/* Hamburger All Button */}
          <button 
            onClick={onToggleSidebar}
            style={{
              background: 'transparent',
              border: '1px solid rgba(255,255,255,0.4)',
              borderRadius: '4px',
              color: '#ffffff',
              padding: '4px 10px',
              cursor: 'pointer',
              fontWeight: 'bold',
              display: 'flex',
              alignItems: 'center',
              gap: '6px',
              fontSize: '14px'
            }}
          >
            <span style={{ fontSize: '16px' }}>☰</span> All
          </button>
          
          <Link to="/" className="sub-nav-item">Home</Link>
          <Link to="/Products" className="sub-nav-item">Products</Link>
          <Link to="/about" className="sub-nav-item">About</Link>
          <Link to="/contact" className="sub-nav-item">Contact</Link>
          <Link to="/cart" className="sub-nav-item">Cart</Link>
          <Link to="/orders" className="sub-nav-item">My Orders</Link>

          {/* Divider separator */}
          <span style={{ color: 'rgba(255,255,255,0.3)', margin: '0 4px' }}>|</span>

          {/* Categories styled identically as nav links */}
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => onSelectCategory && onSelectCategory(cat)}
              className="sub-nav-item"
              style={{
                background: 'transparent',
                border: 'none',
                cursor: 'pointer',
                font: 'inherit',
                color: selectedCategory === cat ? '#ffffff' : '#d0d0d0',
                fontWeight: selectedCategory === cat ? 'bold' : 'normal',
                textDecoration: selectedCategory === cat ? 'underline' : 'none',
                padding: '0 6px'
              }}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="sub-nav-promo">
          <span>Great Indian Festival | Shop early deals now </span>
        </div>
      </div>
    </div>
  );
}

export default TopNavbar;
